//! Independent binomial-tail fixtures and finite-sample coverage checks.
use burn_quantum::photonic::qec::threshold::*;
#[test]
fn clopper_pearson_matches_nist_and_independent_direct_binomial_tail_inversion() {
    // NIST handbook section7.2.4.1 first row; other rows generated by direct
    // binomial-tail sums/recurrence and bisection, not this beta implementation.
    for (n, k, alpha, lo, hi) in [
        (20, 4, 0.1, 0.07135388430861808, 0.40102811733197474),
        (15000, 0, 0.01 / 28., 0., 0.0005752026326164561),
        (
            15000,
            1,
            0.01 / 28.,
            1.1905824885709924e-8,
            0.0007414738618731764,
        ),
        (
            15000,
            100,
            0.01 / 28.,
            0.004548122139913546,
            0.00937665794127196,
        ),
        (
            15000,
            7500,
            0.01 / 28.,
            0.4853960441802001,
            0.5146039558197999,
        ),
        (
            15000,
            14999,
            0.01 / 28.,
            0.9992585261381268,
            0.9999999880941751,
        ),
        (
            1000000,
            123456,
            0.01 / 68.,
            0.12221052009728606,
            0.12470896964658351,
        ),
    ] {
        let got = BinomialInterval::clopper_pearson(k, n, alpha).unwrap();
        assert!(
            (got.lower - lo).abs() < 5e-10,
            "{n} {k}:{} vs{lo}",
            got.lower
        );
        assert!(
            (got.upper - hi).abs() < 5e-10,
            "{n} {k}:{} vs{hi}",
            got.upper
        );
    }
}
#[test]
fn intervals_cover_exact_binomial_laws_at_small_sample_sizes() {
    for n in 1usize..40 {
        for p in [0.001_f64, 0.01, 0.1, 0.3, 0.5, 0.9, 0.99, 0.999] {
            let mut choose = 1.;
            let mut missed = 0.;
            for k in 0..=n {
                let interval = BinomialInterval::clopper_pearson(k, n, 0.05).unwrap();
                let mass = choose * p.powi(k as i32) * (1. - p).powi((n - k) as i32);
                if p < interval.lower || p > interval.upper {
                    missed += mass;
                }
                choose *= ((n - k) as f64) / (k + 1) as f64;
            }
            assert!(missed <= 0.05 + 1e-12);
        }
    }
    assert!(BinomialInterval::clopper_pearson(0, 0, 0.05).is_err());
    assert!(BinomialInterval::simultaneous(0, 100, 0.01, 0).is_err());
    let one = BinomialInterval::clopper_pearson(0, 100, 0.01).unwrap();
    let family = BinomialInterval::simultaneous(0, 100, 0.01, 100).unwrap();
    assert!(family.upper > one.upper);
}
#[test]
fn finite_size_brackets_require_simultaneously_resolved_ordering() {
    let ci = |lower, upper| BinomialInterval { lower, upper };
    assert_eq!(
        compare_sizes(&[(3, ci(0.1, 0.2)), (5, ci(0.03, 0.07)), (7, ci(0.001, 0.02))]).unwrap(),
        FiniteSizeTrend::Suppressed
    );
    assert_eq!(
        compare_sizes(&[(3, ci(0.001, 0.02)), (5, ci(0.03, 0.07)), (7, ci(0.1, 0.2))]).unwrap(),
        FiniteSizeTrend::Increased
    );
    assert_eq!(
        compare_sizes(&[(3, ci(0.01, 0.2)), (5, ci(0.03, 0.07))]).unwrap(),
        FiniteSizeTrend::Unresolved
    );
    assert_eq!(
        compare_sizes(&[(3, ci(0.1, 0.2)), (5, ci(0.03, 0.07)), (7, ci(0.1, 0.2))]).unwrap(),
        FiniteSizeTrend::NonMonotone
    );
    assert_eq!(
        crossing_bracket(&[
            (0.10, FiniteSizeTrend::Suppressed),
            (0.12, FiniteSizeTrend::Unresolved),
            (0.14, FiniteSizeTrend::Increased)
        ])
        .unwrap(),
        Some(FiniteSizeBracket {
            lower: 0.10,
            upper: 0.14
        })
    );
    assert!(
        crossing_bracket(&[
            (0.1, FiniteSizeTrend::Increased),
            (0.2, FiniteSizeTrend::Suppressed)
        ])
        .unwrap()
        .is_none()
    );
}
